/**
 * Starts the Activity server from the environment and wires the process signals. Shared by
 * `src/main.ts` (assets read from `dist/`) and the entry generated by `scripts/compile.ts` (assets
 * embedded in the binary).
 */
import type { AssetStore } from "./http/assets";
import { ConfigError, loadConfig } from "./config";
import { consoleLogger } from "./log";
import { startActivityServer, type RunningActivityServer } from "./server";

export function run(assets?: AssetStore): RunningActivityServer {
  try {
    const config = loadConfig(process.env);
    const running = startActivityServer({ config, assets });
    let stopping = false;
    const shutdown = async (signal: string) => {
      if (stopping) return;
      stopping = true;
      consoleLogger.info("activity server stopping", { signal });
      await running.stop();
      process.exit(0);
    };
    process.on("SIGINT", () => void shutdown("SIGINT"));
    process.on("SIGTERM", () => void shutdown("SIGTERM"));
    return running;
  } catch (error) {
    if (error instanceof ConfigError) {
      consoleLogger.error("invalid configuration", { error: error.message });
      process.exit(78);
    }
    throw error;
  }
}
